/** The artificial 2001 cutoff cannot erase unrelated present-day test records. */
@EnabledIfEnvironmentVariable(named="MP_RUN_MYSQL_TESTS",matches="true")
class RetentionMySqlTest {
    static final Instant NOW=Instant.parse("2001-01-01T00:00:00Z");static JdbcTemplate db;static TransactionTemplate tx;static ObjectMapper mapper;
    @TempDir Path directory;long active,deleting;PrivateObjectStore files;RetentionService service;
    final List<Long> jobs=new ArrayList<>(),exports=new ArrayList<>(),adminExports=new ArrayList<>(),operators=new ArrayList<>(),requests=new ArrayList<>(),tasks=new ArrayList<>();final List<String> keys=new ArrayList<>();List<Map<String,Object>> previousHealth;
    @BeforeAll static void database(){String url=System.getenv("MP_DB_URL");if(url==null||!url.startsWith("jdbc:mysql://127.0.0.1:13306/majorpilot?"))throw new IllegalStateException("Dedicated test database required");var source=new DriverManagerDataSource(url.replace("/majorpilot?","/majorpilot_test?"),System.getenv("MP_DB_USERNAME"),System.getenv("MP_DB_PASSWORD"));Flyway.configure().dataSource(source).locations("classpath:db/migration").cleanDisabled(true).load().migrate();db=new JdbcTemplate(source);tx=new TransactionTemplate(new DataSourceTransactionManager(source));mapper=new ObjectMapper().findAndRegisterModules();}
    @BeforeEach void fixture()throws Exception{active=student("ACTIVE");deleting=student("DELETION_PENDING");files=new PrivateObjectStore(directory.toRealPath().toString());service=new RetentionService(db,tx,mapper,files);previousHealth=db.queryForList("SELECT * FROM mp_retention_status");}
    long student(String status){String id=PublicIds.next(),email="retention-"+id.toLowerCase(Locale.ROOT)+"@example.invalid";db.update("INSERT INTO mp_student_account(public_id,email_normalized,email_display,password_hash,status,created_at) VALUES(?,?,?,'synthetic-unused',?,?)",id,email,email,status,at(NOW.minus(Duration.ofDays(400))));return db.queryForObject("SELECT id FROM mp_student_account WHERE public_id=?",Long.class,id);}
    static Timestamp at(Instant time){return Timestamp.from(time);}
    static long n(Map<String,Object> row,String key){return ((Number)row.get(key)).longValue();}
    long event(long student,Instant received){String id=PublicIds.next();db.update("INSERT INTO mp_product_event(event_id,event_name,event_version,source,occurred_at,received_at,student_id,properties_json) VALUES(?,'synthetic.retention','v1','BACKEND',?,?,?,'{}')",id,at(received),at(received),student);return db.queryForObject("SELECT id FROM mp_product_event WHERE event_id=?",Long.class,id);}
    long ai(long student,Instant created,String status){String id=PublicIds.next();db.update("INSERT INTO mp_ai_call(public_id,student_id,call_kind,provider,prompt_version,input_schema_version,input_sha256,input_field_keys_json,status,duration_ms,created_at) VALUES(?,?,'HINT','STATIC','synthetic','synthetic',?,'[]',?,0,?)",id,student,"0".repeat(64),status,at(created));return db.queryForObject("SELECT id FROM mp_ai_call WHERE public_id=?",Long.class,id);}
    long job(String type,Long student,String target,long targetId,String status,Instant completed,String checkpoint){String id=PublicIds.next();db.update("INSERT INTO mp_background_job(public_id,job_type,business_key,owner_student_id,target_type,target_id,status,checkpoint_json,completed_at,created_at) VALUES(?,?,?,?,?,?,?,?,?,?)",id,type,"retention-test:"+id,student,target,targetId,status,checkpoint,completed==null?null:at(completed),at(NOW.minus(Duration.ofDays(200))));long internal=db.queryForObject("SELECT id FROM mp_background_job WHERE public_id=?",Long.class,id);jobs.add(internal);return internal;}
    int exists(String table,long id){return db.queryForObject("SELECT COUNT(*) FROM "+table+" WHERE id=?",Integer.class,id);}
    @AfterEach void cleanup(){for(String key:keys)files.delete(key);for(long id:adminExports){db.update("DELETE FROM mp_admin_export_student WHERE export_id=?",id);db.update("DELETE FROM mp_admin_export WHERE id=?",id);}for(long id:exports)db.update("DELETE FROM mp_student_data_export WHERE id=?",id);for(long id:requests)db.update("DELETE FROM mp_account_deletion_request WHERE id=?",id);
        for(long student:List.of(active,deleting)){db.update("DELETE FROM mp_sensitive_audit WHERE owner_student_id=?",student);db.update("DELETE FROM mp_product_event WHERE student_id=?",student);db.update("DELETE FROM mp_ai_call WHERE student_id=?",student);db.update("DELETE FROM mp_report WHERE student_id=?",student);db.update("DELETE FROM mp_evidence_snapshot WHERE student_id=?",student);db.update("DELETE FROM mp_background_job WHERE owner_student_id=?",student);db.update("DELETE FROM mp_experience_run WHERE student_id=?",student);db.update("DELETE FROM mp_decision_profile WHERE student_id=?",student);db.update("DELETE FROM mp_student_account WHERE id=?",student);}for(long id:jobs)db.update("DELETE FROM mp_background_job WHERE id=?",id);for(long operator:operators)db.update("DELETE FROM sys_user WHERE user_id=?",operator);for(long task:tasks)db.update("DELETE FROM mp_task_version WHERE id=?",task);
        Set<String> old=new HashSet<>();for(var row:previousHealth){old.add((String)row.get("policy_key"));db.update("INSERT INTO mp_retention_status(policy_key,last_started_at,last_completed_at,last_error_code,deleted_count,next_due_at) VALUES(?,?,?,?,?,?) ON DUPLICATE KEY UPDATE last_started_at=VALUES(last_started_at),last_completed_at=VALUES(last_completed_at),last_error_code=VALUES(last_error_code),deleted_count=VALUES(deleted_count),next_due_at=VALUES(next_due_at)",row.get("policy_key"),row.get("last_started_at"),row.get("last_completed_at"),row.get("last_error_code"),row.get("deleted_count"),row.get("next_due_at"));}for(var policy:RetentionPolicy.values())if(!old.contains(policy.name()))db.update("DELETE FROM mp_retention_status WHERE policy_key=?",policy.name());
    }
    @Test void metadataBoundariesKeepFutureActiveAndDeletingSubjectsAndRespectBatch(){Instant boundary=NOW.minus(Duration.ofDays(90));long old=ai(active,boundary.minusMillis(1),"SUCCEEDED"),exact=ai(active,boundary,"FAILED"),running=ai(active,boundary.minusSeconds(100),"IN_PROGRESS"),pending=ai(deleting,boundary.minusSeconds(100),"FAILED");assertEquals(1,service.run(RetentionPolicy.AI_METADATA,NOW,100,()->true));assertEquals(0,exists("mp_ai_call",old));for(long keep:List.of(exact,running,pending))assertEquals(1,exists("mp_ai_call",keep));
        long a=event(active,NOW.minus(Duration.ofDays(181))),b=event(active,NOW.minus(Duration.ofDays(182))),future=event(active,NOW.plusSeconds(1)),deletion=event(deleting,NOW.minus(Duration.ofDays(200)));assertEquals(1,service.run(RetentionPolicy.PRODUCT_EVENTS,NOW,1,()->true));assertEquals(1,exists("mp_product_event",a)+exists("mp_product_event",b));assertEquals(1,service.run(RetentionPolicy.PRODUCT_EVENTS,NOW,1,()->true));assertEquals(0,service.run(RetentionPolicy.PRODUCT_EVENTS,NOW,1,()->true));assertEquals(1,exists("mp_product_event",future));assertEquals(1,exists("mp_product_event",deletion));
    }
    @Test void terminalJobAgeDoesNotEraseActiveDeletionOrUnknownCompletion(){long old=job("EVIDENCE_BUILD",active,"EXPERIENCE_RUN",0,"SUCCEEDED",NOW.minus(Duration.ofDays(31)),"{}"),failed=job("REPORT_GENERATE",active,"REPORT_VERSION",0,"FAILED",NOW.minus(Duration.ofDays(91)),"{}"),boundary=job("EVIDENCE_BUILD",active,"EXPERIENCE_RUN",0,"SUCCEEDED",NOW.minus(Duration.ofDays(30)),"{}"),noTime=job("EVIDENCE_BUILD",active,"EXPERIENCE_RUN",0,"FAILED",null,"{}"),deletion=job("ACCOUNT_DELETE",deleting,"ACCOUNT_DELETION_REQUEST",0,"FAILED",NOW.minus(Duration.ofDays(150)),"{}"),running=job("EVIDENCE_BUILD",active,"EXPERIENCE_RUN",0,"RUNNING",NOW.minus(Duration.ofDays(200)),"{}");assertEquals(2,service.run(RetentionPolicy.TERMINAL_JOBS,NOW,100,()->true));for(long gone:List.of(old,failed))assertEquals(0,exists("mp_background_job",gone));for(long keep:List.of(boundary,noTime,deletion,running))assertEquals(1,exists("mp_background_job",keep));}
    record Artifact(long id,long job,String key){}
    Artifact export(long student,Instant expiry,Instant completed,String jobStatus){String publicId=PublicIds.next(),key="student/"+PublicIds.next()+".zip";keys.add(key);var stored=files.write(key,"synthetic-private-export".getBytes(java.nio.charset.StandardCharsets.UTF_8));db.update("INSERT INTO mp_student_data_export(public_id,student_id,scope,status,object_key,file_sha256,file_size_bytes,requested_at,completed_at,expires_at) VALUES(?,?,'REPORTS_ONLY','READY',?,?,?,?,?,?)",publicId,student,key,stored.sha256(),stored.size(),at(completed.minusSeconds(1)),at(completed),at(expiry));long id=db.queryForObject("SELECT id FROM mp_student_data_export WHERE public_id=?",Long.class,publicId);exports.add(id);long job=job("STUDENT_EXPORT",student,"STUDENT_DATA_EXPORT",id,jobStatus,completed,"{\"artifactKeys\":[\""+key+"\"],\"phase\":\"PUBLISHED\"}");return new Artifact(id,job,key);}
    @Test void filesExpireFirstAndMetadataNeedsThirtyDaysWhileActiveAndDeletingExportsStay(){Artifact expired=export(active,NOW.minusSeconds(1),NOW.minus(Duration.ofDays(2)),"SUCCEEDED"),future=export(active,NOW.plusSeconds(1),NOW.minus(Duration.ofDays(1)),"SUCCEEDED"),busy=export(active,NOW.minusSeconds(1),NOW.minus(Duration.ofDays(2)),"RUNNING"),deletion=export(deleting,NOW.minusSeconds(1),NOW.minus(Duration.ofDays(2)),"CANCELLED");assertEquals(1,service.run(RetentionPolicy.EXPORT_FILES,NOW,100,()->true));assertThrows(IllegalStateException.class,()->files.read(expired.key));assertEquals("EXPIRED",db.queryForObject("SELECT status FROM mp_student_data_export WHERE id=?",String.class,expired.id));assertNull(db.queryForObject("SELECT object_key FROM mp_student_data_export WHERE id=?",String.class,expired.id));for(var keep:List.of(future,busy,deletion))assertTrue(files.read(keep.key).length>0);assertEquals(0,service.run(RetentionPolicy.EXPORT_METADATA,NOW,100,()->true));db.update("UPDATE mp_student_data_export SET completed_at=? WHERE id=?",at(NOW.minus(Duration.ofDays(31))),expired.id);assertEquals(1,service.run(RetentionPolicy.EXPORT_METADATA,NOW,100,()->true));assertEquals(0,exists("mp_background_job",expired.job));assertEquals(0,exists("mp_student_data_export",expired.id));}
    Artifact adminExport(long member){String name="rt-"+PublicIds.next().substring(10),id=PublicIds.next(),key="admin/"+PublicIds.next()+".csv";db.update("INSERT INTO sys_user(user_name,nick_name,password,status,del_flag) VALUES(?,'Synthetic retention operator','unused','0','0')",name);long operator=db.queryForObject("SELECT user_id FROM sys_user WHERE user_name=?",Long.class,name);operators.add(operator);keys.add(key);var stored=files.write(key,"safe,synthetic\r\n".getBytes(java.nio.charset.StandardCharsets.UTF_8));Instant old=NOW.minus(Duration.ofDays(40));db.update("INSERT INTO mp_admin_export(public_id,operator_id,dataset,filters_json,fields_json,purpose,status,object_key,file_sha256,file_size_bytes,row_count,requested_at,completed_at,expires_at) VALUES(?,?,'STUDENTS','{}','[\"studentId\"]','Synthetic retention fixture','READY',?,?,?,1,?,?,?)",id,operator,key,stored.sha256(),stored.size(),at(old),at(old),at(old.plus(Duration.ofDays(1))));long internal=db.queryForObject("SELECT id FROM mp_admin_export WHERE public_id=?",Long.class,id);adminExports.add(internal);db.update("INSERT INTO mp_admin_export_student(export_id,student_id) VALUES(?,?)",internal,member);String jobId=PublicIds.next();db.update("INSERT INTO mp_background_job(public_id,job_type,business_key,owner_operator_id,target_type,target_id,status,checkpoint_json,completed_at) VALUES(?,'ADMIN_EXPORT',?,?,'ADMIN_EXPORT',?,'SUCCEEDED',?,?)",jobId,"admin-export:"+id,operator,internal,"{\"artifactKeys\":[\""+key+"\"]}",at(old));long job=db.queryForObject("SELECT id FROM mp_background_job WHERE public_id=?",Long.class,jobId);jobs.add(job);return new Artifact(internal,job,key);}
    @Test void adminFilesAndMembershipExpireButDeletingMemberRemainsOwnedByDeletion(){var expired=adminExport(active);var protectedExport=adminExport(deleting);assertEquals(1,service.run(RetentionPolicy.EXPORT_FILES,NOW,100,()->true));assertThrows(IllegalStateException.class,()->files.read(expired.key));assertTrue(files.read(protectedExport.key).length>0);assertEquals(1,service.run(RetentionPolicy.EXPORT_METADATA,NOW,100,()->true));assertEquals(0,exists("mp_admin_export",expired.id));assertEquals(0,exists("mp_background_job",expired.job));assertEquals(0,db.queryForObject("SELECT COUNT(*) FROM mp_admin_export_student WHERE export_id=?",Integer.class,expired.id));assertEquals(1,exists("mp_admin_export",protectedExport.id));}
    @Test void failedObjectDeleteKeepsDatabaseKeysAndCheckpointUntilRetrySucceeds()throws Exception{var artifact=export(active,NOW.minusSeconds(1),NOW.minus(Duration.ofDays(40)),"SUCCEEDED");var broken=new PrivateObjectStore(directory.toRealPath().toString()){@Override public void delete(String key){throw new IllegalStateException("PRIVATE_EXPORT_STORAGE_UNAVAILABLE");}};var bad=new RetentionService(db,tx,mapper,broken);assertThrows(IllegalStateException.class,()->bad.run(RetentionPolicy.EXPORT_FILES,NOW,100,()->true));assertEquals(artifact.key,db.queryForObject("SELECT object_key FROM mp_student_data_export WHERE id=?",String.class,artifact.id));assertTrue(db.queryForObject("SELECT checkpoint_json FROM mp_background_job WHERE id=?",String.class,artifact.job).contains(artifact.key));assertTrue(files.read(artifact.key).length>0);assertEquals(1,service.run(RetentionPolicy.EXPORT_FILES,NOW,100,()->true));assertEquals(1,service.run(RetentionPolicy.EXPORT_METADATA,NOW,100,()->true));}
    long request(long student,Instant requested,boolean confirmed){String id=PublicIds.next();db.update("INSERT INTO mp_account_deletion_request(public_id,student_id,status,requested_at,confirmed_at,receipt_id,receipt_secret_hash,receipt_expires_at) VALUES(?,?,?,?,?,?,?,?)",id,student,confirmed?"CONFIRMED":"REQUESTED",at(requested),confirmed?at(requested):null,PublicIds.next(),Secrets.hash(PublicIds.next()),at(requested.plus(Duration.ofDays(7))));long internal=db.queryForObject("SELECT id FROM mp_account_deletion_request WHERE public_id=?",Long.class,id);requests.add(internal);return internal;}
    @Test void oldUnconfirmedIsCancelledDetachedAndExpiresWithoutTouchingConfirmedDeletion(){long old=request(active,NOW.minus(Duration.ofDays(8)),false),confirmed=request(deleting,NOW.minus(Duration.ofDays(40)),true);assertEquals(1,service.run(RetentionPolicy.UNCONFIRMED_DELETIONS,NOW,100,()->true));assertEquals("CANCELLED",db.queryForObject("SELECT status FROM mp_account_deletion_request WHERE id=?",String.class,old));assertNull(db.queryForObject("SELECT student_id FROM mp_account_deletion_request WHERE id=?",Long.class,old));assertEquals(1,service.run(RetentionPolicy.EXPIRED_RECEIPTS,NOW,100,()->true));assertEquals(0,exists("mp_account_deletion_request",old));assertEquals(1,exists("mp_account_deletion_request",confirmed));assertEquals(1,exists("mp_student_account",active));}
    static final class MutableClock extends Clock{Instant now=NOW;public ZoneId getZone(){return ZoneOffset.UTC;}public Clock withZone(ZoneId zone){return this;}public Instant instant(){return now;}}
    @Test void systemLeaseSurvivesRecreationAndOldLeaseCannotRunOrPublish(){var clock=new MutableClock();db.update("UPDATE mp_retention_status SET next_due_at=NULL WHERE policy_key='STALE_PARTIALS'");var first=new RetentionJobs(db,tx,mapper,service,clock);var second=new RetentionJobs(db,tx,mapper,service,clock);try{assertTrue(first.enqueue(RetentionPolicy.STALE_PARTIALS,clock.instant(),10));assertFalse(first.enqueue(RetentionPolicy.STALE_PARTIALS,clock.instant(),10));var old=first.claim("old-retention");assertNotNull(old);jobs.add(old.id());clock.now=clock.now.plusSeconds(61);var next=second.claim("replacement-retention");assertEquals(old.generation()+1,next.generation());assertFalse(first.heartbeat(old));assertFalse(first.process(old));assertTrue(second.process(next));assertEquals(2,db.queryForObject("SELECT attempt_count FROM mp_background_job WHERE id=?",Integer.class,next.id()));assertEquals("SUCCEEDED",db.queryForObject("SELECT status FROM mp_background_job WHERE id=?",String.class,next.id()));assertNotNull(db.queryForObject("SELECT last_completed_at FROM mp_retention_status WHERE policy_key='STALE_PARTIALS'",Timestamp.class));assertEquals(0,db.queryForObject("SELECT COUNT(*) FROM mp_background_job WHERE id=? AND (owner_student_id IS NOT NULL OR owner_operator_id IS NOT NULL)",Integer.class,next.id()));}finally{first.stop();second.stop();}}
    @Test void retryBudgetIsDurableAndHealthStoresOnlySafeCode(){var clock=new MutableClock();db.update("UPDATE mp_retention_status SET next_due_at=NULL WHERE policy_key='AI_METADATA'");var worker=new RetentionJobs(db,tx,mapper,service,clock);try{assertTrue(worker.enqueue(RetentionPolicy.AI_METADATA,NOW,10));for(int attempt=1;attempt<=3;attempt++){var lease=worker.claim("retry-worker-"+attempt);assertNotNull(lease);if(attempt==1)jobs.add(lease.id());assertTrue(worker.fail(lease,"raw vendor payload must never be stored"));assertEquals(attempt,db.queryForObject("SELECT attempt_count FROM mp_background_job WHERE id=?",Integer.class,lease.id()));assertEquals(attempt==3?"FAILED":"RETRY_WAIT",db.queryForObject("SELECT status FROM mp_background_job WHERE id=?",String.class,lease.id()));assertEquals("RETENTION_BATCH_FAILED",db.queryForObject("SELECT last_error_code FROM mp_retention_status WHERE policy_key='AI_METADATA'",String.class));clock.now=clock.now.plusSeconds(attempt==1?5:30);}assertNull(worker.claim("fourth-attempt"));}finally{worker.stop();}}
    @Test void heartbeatIsNotBlockedByBatchAndLateBatchCannotPublishAfterTakeover()throws Exception{
        var entered=new CountDownLatch(1);var release=new CountDownLatch(1);var clock=new MutableClock();db.update("UPDATE mp_retention_status SET next_due_at=NULL WHERE policy_key='STALE_PARTIALS'");
        var slow=new RetentionService(db,tx,mapper,files){@Override public long run(RetentionPolicy policy,Instant asOf,int batch,BooleanSupplier lease){entered.countDown();try{if(!release.await(5,TimeUnit.SECONDS))throw new IllegalStateException("Synthetic latch timeout");}catch(InterruptedException e){Thread.currentThread().interrupt();throw new IllegalStateException(e);}return 0;}};
        var worker=new RetentionJobs(db,tx,mapper,slow,clock);try(var pool=Executors.newFixedThreadPool(2)){assertTrue(worker.enqueue(RetentionPolicy.STALE_PARTIALS,NOW,10));var old=worker.claim("slow-old");jobs.add(old.id());var processing=pool.submit(()->worker.process(old));assertTrue(entered.await(2,TimeUnit.SECONDS));clock.now=clock.now.plusSeconds(31);assertTrue(pool.submit(()->worker.heartbeat(old)).get(2,TimeUnit.SECONDS));clock.now=clock.now.plusSeconds(61);var fresh=worker.claim("fresh-retention");assertNotNull(fresh);release.countDown();assertFalse(processing.get(2,TimeUnit.SECONDS));assertEquals("RUNNING",db.queryForObject("SELECT status FROM mp_background_job WHERE id=?",String.class,old.id()));assertTrue(worker.process(fresh));}finally{release.countDown();worker.stop();}
    }
}
